from common import *

def main():
 verify();q=load('QUALIFICATION.json');results=load('RESULTS.json');before=load('PRESERVATION_BEFORE.json');assert all(Path(p).is_file() and sha(Path(p))==h for p,h in before.items())
 assert not (R/'targets').exists() and not (R/'TARGET_MANIFEST.json').exists();cells=q['cells'];counts={k:sum(r['kind']==k and r['status']=='COMPLETE' for r in results) for k in ['positive','negative']};exceptions=[r for r in results if r['status']!='COMPLETE']
 text=['# Phase 9: later month annotations — calibration result','',f"**Qualification: {q['status']}. {sum(c['cell_pass'] for c in cells)}/32 cells passed; every cell was required.**",'',f"Completed: {counts['positive']}/160 positive and {counts['negative']}/160 negative datasets. Scorer/search exceptions: {len(exceptions)}.",'', '**Native herbal and native zodiac tracks remain CLOSED. No annotation-target fit was run. Phase 8 remains FAIL and unchanged.** This run stops after the explicitly requested registration/calibration stage, including on PASS.','', '## Full registered gate table','', '| Language | Generator | Mapping recovered /5 | Recovery + max-test rejection /5 | Negative rejections /5 | Pass |','|---|---|---:|---:|---:|---|']
 for c in cells:text.append(f"| {c['language']} | {c['encoder']} | {c['mapping_recovered']} | {c['positive_recovery_and_rejection']} | {c['negative_rejections']} | {c['cell_pass']} |")
 text+=['','Each cell requires at least 4/5 positive recovery-and-rejection trials, at most 1/5 negative rejections, and completion of all ten trials. Trials and schedules are paired, not independent text samples. No pooled rate overrides a cell failure.','', '## Cited historical candidate list','', '| Month | Latin | Italian (1495) | German | Occitan |','|---|---|---|---|---|']
 source=load('PERIOD_NAMES.json')
 for month in range(3,13):text.append('| '+str(month)+' | '+' | '.join(next(row['form'] for row in source if row['month']==month and row['language']==lang) for lang in LANGS)+' |')
 text+=['', 'Every language/month form, exact locator, source URL, period/witness qualification and normalized spelling is retained in PERIOD_NAMES.json and NORMALIZED_NAMES.json. Latin is from a catalogue transcript of the Brandeis Hours c1420–1430, checked against The National Archives reference table; Italian headings were inspected in the 1495 scan; German combines historical regional quotations/lemma evidence (not one dialect); Occitan comes from historical Raynouard entries quoting medieval traditions. These are not equally direct or contemporaneous attestations. Italian spellings remain as printed. German wintermonat intentionally represents both November and December. The candidate list is bounded, not exhaustive.','', '## Meaning and limits','', 'The exact objective is the largest number of full label/name matches under one consistent model and language. Every observed and shuffled dataset maximizes over monoalphabetic substitution, beginning/interior/end substitution, all six fixed published Naibbe tables, and all four languages. The statistic includes length/repetition-pattern compatibility. Significance does not uniquely identify phonetic encoding, a language, or a historical generator.','', 'Plaintext normalization uses the author-derived 23-letter rule across all families/languages. Cipher symbols retain their own identity, with no w/j/k spelling conversion. Parenthesized annotation letters receive a frozen include/omit expansion rule applied identically in calibration and future target handling. No hand correction, modern spelling replacement, edit distance, reversal or post-outcome name addition.','', 'Known generating-language/family recovery is evaluated without giving truth to the fitter. Mono/position recovery covers only observed mapping entries. Naibbe recovery concerns the global fixed table, not a stochastic deck sequence or a unique segmentation. Non-unique true-table maxima fail recovery. Family selection itself need not be unique because positional substitution contains monoalphabetic substitution.','', 'The calibration uses twelve slots with duplicate April/May names, four frozen ten-month lists, five seeds and declared parenthesis patterns. It is a finite exact-string support test, not independent language corpora, held-out name generalization, handwriting recognition or a botanical crib validation. French is not a candidate language; the historical Romance annotations cannot be assigned a language by choosing the best of these four.','', 'Naibbe tables were designed using Voynich statistics and are NOT blind controls. Only the six fixed-table models are tested; stochastic mixed decks and other verbose families are outside scope.','', '## Receipts and preserved stop','', 'REGISTRATION.json freezes all code, candidates, sources, seeds and assignments before generation/scoring. DATA_READY.json seals the generated bank before fitting. Each results/<id>/OBSERVED.json contains every model witness; NULLS.jsonl.gz retains all 99 assignments and every refitted model result, including mappings, bounds and search receipts. RESULT.json records exact recovery and p-values. Source/data/scorer/search failures remain distinct from gate failures.','',f"Preservation verified: {len(before)} pre-existing Phase 8 and Phase 9 source-audit files remain byte-identical. Original source freeze, prior failures and registrations were not changed. No native target was opened, no target fit was run, and no retuning or replacement bank followed qualification. No translation claims.",'']
 (R/'REPORT.md').write_text('\n'.join(text),encoding='utf8');dump('VERIFICATION.json',dict(status='PASS_PRESERVATION_AND_BOUNDARIES',qualification=q['status'],preserved_files=len(before),changed_files=0,annotation_target_fits=False,native_tracks_scored=False,Phase8_FAIL_preserved=True,scorer_search_exceptions=exceptions))
 dump('RESULT_HASHES.json',{str(p.relative_to(R)):sha(p) for p in (R/'results').rglob('*') if p.is_file()});dump('OUTPUT_HASHES.json',{p.name:sha(p) for p in R.iterdir() if p.is_file() and p.name!='OUTPUT_HASHES.json'})
 print(json.dumps(dict(qualification=q['status'],passing_cells=sum(c['cell_pass'] for c in cells),complete=counts,exceptions=len(exceptions),preserved_files=len(before)),indent=2))
if __name__=='__main__':main()
